// Optics and under-barrel attachments (2026-11-16, Yan: "older weapons like the Mosin could use a PU 2x scope, newer weapons with rails 4x and 8x, assault rifles an ACOG 4x,
// sidearms red dots or a laser", then "SMGs get a red dot, shotguns nothing"). Sprites: ArtSource/weapons/attachments.py (Resources/Sprites/Attachments); where each sits and
// which gun takes what: GameData/OpticMounts.cs (generated by ArtSource/weapons/mounts.py). State lives on the Weapon (Optic = sight on the rail, Under = laser under the barrel), so
// every player's gun has its own; nothing here is global. Co-op: the effects below are applied where a player fires (Rt.PlayerFire) and aims (Rt camera), per player.
using System.Collections.Generic;
using GameData;
using UnityEngine;

namespace GameCore
{
    public static class Optics
    {
        public class Def
        {
            public string Id, Name, Kind;                 // Kind: "scope" (looks further), "dot" (a red-dot sight), "laser"
            public bool Under;                            // hangs under the barrel (the laser) instead of sitting on the rail
            public float Reach;                           // scopes: how far the camera leans toward the mouse while you aim (1/(1-Reach) times the cursor's offset); the gun's own lean stays if it is bigger
            public float LookMul;                         // scopes: your look reach while aiming (dusk, rain and fog cut it; a scope gives some back, capped at Vision.MaxRadius)
            public float AimedSpread = 1f, HipSpread = 1f;   // spread multipliers when fully steady / from the hip (blended by how steady you are)
            public float SteadyMul = 1f;                  // how fast the aim steadies (a red dot is quick, a big scope is slow)
            public float View;                            // scopes: the lit circle's radius as a share of the screen height (the rest of the screen darkens)
            public Vector2 Pivot;                         // the sprite's mount point, texture px
        }
        public static readonly Dictionary<string, Def> All = new Dictionary<string, Def>
        {
            ["pu2"] = new Def { Id = "pu2", Name = "PU 2x", Kind = "scope", Reach = 0.80f, LookMul = 1.15f, AimedSpread = 0.90f, SteadyMul = 0.95f, View = 0.34f, Pivot = new Vector2(31, 16) },
            ["acog"] = new Def { Id = "acog", Name = "ACOG 4x", Kind = "scope", Reach = 0.78f, LookMul = 1.20f, AimedSpread = 0.85f, SteadyMul = 0.90f, View = 0.30f, Pivot = new Vector2(19, 19) },
            ["scope8"] = new Def { Id = "scope8", Name = "8x scope", Kind = "scope", Reach = 0.88f, LookMul = 1.35f, AimedSpread = 0.75f, SteadyMul = 0.75f, View = 0.26f, Pivot = new Vector2(41, 19) },
            ["reddot"] = new Def { Id = "reddot", Name = "Red dot", Kind = "dot", AimedSpread = 0.95f, HipSpread = 0.90f, SteadyMul = 1.30f, Pivot = new Vector2(13, 16) },
            ["laser"] = new Def { Id = "laser", Name = "Laser", Kind = "laser", Under = true, AimedSpread = 0.97f, HipSpread = 0.80f, Pivot = new Vector2(11, 1) },
        };
        /// <summary>The attachment sprites are drawn at 6 texture px to one in-game pixel on every gun, so one set fits all.</summary>
        public const float TexPerPixel = 6f;

        static string KeyOf(Weapon w) => w?.Db == null ? null : WeaponArt.Identify(w.Db).key;
        public static Def OpticOf(Weapon w) => w?.Optic != null && All.TryGetValue(w.Optic, out var d) && !d.Under ? d : null;
        public static Def UnderOf(Weapon w) => w?.Under != null && All.TryGetValue(w.Under, out var d) && d.Under ? d : null;
        public static bool Scoped(Weapon w) => OpticOf(w)?.Kind == "scope";

        /// <summary>What this gun may carry (empty when nothing).</summary>
        public static string[] AllowedFor(Weapon w) => KeyOf(w) is string k && OpticMounts.Allowed.TryGetValue(k, out var a) ? a : new string[0];

        /// <summary>Fit one (or "" / null to take that slot's attachment off). false when the gun cannot take it.</summary>
        public static bool Fit(Weapon w, string id)
        {
            if (w == null) return false;
            if (string.IsNullOrEmpty(id)) { w.Optic = null; return true; }
            if (!All.TryGetValue(id, out var d) || System.Array.IndexOf(AllowedFor(w), id) < 0) return false;
            if (d.Under) w.Under = id; else w.Optic = id;
            return true;
        }
        /// <summary>The Testing Ground's button: none, then each sight this gun takes, then none again.</summary>
        public static string CycleOptic(Weapon w)
        {
            var sights = new List<string>(); foreach (var id in AllowedFor(w)) if (!All[id].Under) sights.Add(id);
            if (sights.Count == 0) { if (w != null) w.Optic = null; return null; }
            int at = w?.Optic == null ? -1 : sights.IndexOf(w.Optic);
            w.Optic = at + 1 >= sights.Count ? null : sights[at + 1];
            return w.Optic;
        }
        public static string ToggleUnder(Weapon w)
        {
            if (w == null) return null;
            bool ok = System.Array.IndexOf(AllowedFor(w), "laser") >= 0;
            w.Under = ok && w.Under == null ? "laser" : null;
            return w.Under;
        }

        // ---- what they do (all per weapon, so per player) ----
        /// <summary>A multiplier on your spread: aimed (steady = 1) or from the hip (0), from the sight and the laser.</summary>
        public static float SpreadMul(Weapon w, float steady)
        {
            float m = 1f;
            foreach (var d in new[] { OpticOf(w), UnderOf(w) }) if (d != null) m *= Mathf.Lerp(d.HipSpread, d.AimedSpread, Mathf.Clamp01(steady));
            return m;
        }
        public static float SteadyMul(Weapon w) { float m = 1f; foreach (var d in new[] { OpticOf(w), UnderOf(w) }) if (d != null) m *= d.SteadyMul; return m; }
        /// <summary>How far the camera leans toward the mouse while aiming: the gun's own lean, or more with a scope.</summary>
        public static float Reach(Weapon w, float baseline) { var d = OpticOf(w); return d != null && d.Kind == "scope" ? Mathf.Max(baseline, d.Reach) : baseline; }
        public static float LookMul(Weapon w, bool aiming) { var d = OpticOf(w); return aiming && d != null && d.Kind == "scope" ? d.LookMul : 1f; }

        // ---- the sprites ----
        static readonly Dictionary<string, Sprite> Sprites = new Dictionary<string, Sprite>();
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] static void ResetCaches() => Sprites.Clear();
        public static Sprite SpriteOf(string id)
        {
            if (id == null || !All.TryGetValue(id, out var d)) return null;
            if (Sprites.TryGetValue(id, out var hit)) return hit;
            var tex = Resources.Load<Texture2D>("Sprites/Attachments/att_" + id);
            if (tex == null) return Sprites[id] = null;
            tex.filterMode = FilterMode.Bilinear;
            return Sprites[id] = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(d.Pivot.x / tex.width, 1f - d.Pivot.y / tex.height), WeaponArt.PixelsPerUnit * TexPerPixel, 0, SpriteMeshType.FullRect);
        }
    }
}
